import React, { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useTheme } from '../context/ThemeContext';
import { getFeaturedProducts } from '../services/api';
import ProductCard from '../components/ProductCard';

const HomeRebuild = () => {
  const { isDarkMode } = useTheme();
  const navigate = useNavigate();

  const [searchDraft, setSearchDraft] = useState('');
  const [featured, setFeatured] = useState([]);
  const [loading, setLoading] = useState(true);

  const categories = useMemo(
    () => [
      { key: 'groceries', label: 'Grocery', emoji: '\uD83D\uDED2' },
      { key: 'fashion', label: 'Fashion', emoji: '\uD83D\uDC55' },
      { key: 'electronics', label: 'Mobiles', emoji: '\uD83D\uDCF1' },
      { key: 'electronics', label: 'Electronics', emoji: '\uD83D\uDCBB' },
      { key: 'home', label: 'Home', emoji: '\uD83C\uDFE0' },
      { key: 'beauty', label: 'Beauty', emoji: '\uD83E\uDDF4' },
      { key: 'accessories', label: 'Accessories', emoji: '\uD83D\uDC5C' },
      { key: 'sweets', label: 'Sweets', emoji: '\uD83C\uDF6C' }
    ],
    []
  );

  useEffect(() => {
    let mounted = true;
    const load = async () => {
      try {
        setLoading(true);
        const res = await getFeaturedProducts();
        if (!mounted) return;
        setFeatured(Array.isArray(res.data) ? res.data : []);
      } catch {
        if (!mounted) return;
        setFeatured([]);
      } finally {
        if (mounted) setLoading(false);
      }
    };
    load();
    return () => {
      mounted = false;
    };
  }, []);

  const goToProducts = (params) => {
    const sp = new URLSearchParams(params);
    navigate(`/products?${sp.toString()}`);
  };

  return (
    <div className="space-y-6">
      {/* Category strip (Flipkart-like) */}
      <section className={`rounded-2xl border overflow-hidden ${isDarkMode ? 'bg-gray-900/60 border-white/10' : 'bg-white border-gray-200'}`}>
        <div className="px-4 py-4 overflow-x-auto">
          <div className="flex items-center gap-4 min-w-max">
            {categories.map((c) => (
              <button
                key={`${c.key}-${c.label}`}
                type="button"
                onClick={() => goToProducts({ category: c.key })}
                className={`flex flex-col items-center justify-center w-24 px-3 py-2 rounded-2xl border transition ${
                  isDarkMode ? 'border-white/10 hover:bg-white/5' : 'border-gray-200 hover:bg-gray-50'
                }`}
              >
                <div className="w-12 h-12 rounded-2xl bg-gradient-to-r from-blue-600 to-cyan-500 text-white flex items-center justify-center text-2xl shadow">
                  {c.emoji}
                </div>
                <div className={`mt-2 text-xs font-bold ${isDarkMode ? 'text-gray-200' : 'text-gray-800'}`}>{c.label}</div>
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* Big banner + search */}
      <section className={`rounded-2xl border overflow-hidden ${isDarkMode ? 'bg-gray-900/60 border-white/10' : 'bg-white border-gray-200'}`}>
        <div className="p-5 md:p-8">
          <div className="flex flex-col lg:flex-row gap-6">
            <div className="flex-1">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-2xl overflow-hidden shadow">
                  <img src="/icon.svg" alt="Pinqoza" className="w-full h-full" draggable="false" />
                </div>
                <div className={`text-sm font-semibold ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>Pinqoza</div>
              </div>
              <h1 className={`mt-3 text-2xl md:text-4xl font-extrabold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>Big Saving Days</h1>
              <p className={`mt-2 text-sm md:text-base ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                Deals on mobiles, fashion, groceries, home & more.
              </p>

              <form
                onSubmit={(e) => {
                  e.preventDefault();
                  const q = searchDraft.trim();
                  if (!q) return;
                  goToProducts({ search: q });
                }}
                className="mt-4"
              >
                <div className={`flex items-center gap-2 p-2 rounded-2xl border ${isDarkMode ? 'border-white/10 bg-black/40' : 'border-gray-200 bg-gray-50'}`}>
                  <input
                    value={searchDraft}
                    onChange={(e) => setSearchDraft(e.target.value)}
                    placeholder="Search for products, brands and more"
                    className={`flex-1 bg-transparent outline-none px-3 py-2 ${
                      isDarkMode ? 'text-white placeholder-gray-500' : 'text-gray-900 placeholder-gray-400'
                    }`}
                  />
                  <button type="submit" className="px-5 py-2 rounded-xl bg-gradient-to-r from-blue-600 to-cyan-500 text-white font-semibold">
                    Search
                  </button>
                </div>
              </form>

              <div className="mt-4 flex flex-wrap gap-2">
                {['iPhone', 'Sneakers', 'Headphones', 'Rice', 'Serum'].map((t) => (
                  <button
                    key={t}
                    type="button"
                    onClick={() => goToProducts({ search: t })}
                    className={`px-3 py-1.5 rounded-full text-xs font-semibold border transition ${
                      isDarkMode ? 'border-white/10 text-gray-200 hover:bg-white/5' : 'border-gray-200 text-gray-800 hover:bg-gray-100'
                    }`}
                  >
                    {t}
                  </button>
                ))}
              </div>
            </div>

            {/* Offer card */}
            <div className={`w-full lg:w-[380px] rounded-2xl border overflow-hidden ${isDarkMode ? 'border-white/10 bg-black/40' : 'border-gray-200 bg-gray-50'}`}>
              <div className="p-6">
                <div className="inline-flex items-center gap-2 text-xs font-bold px-3 py-1 rounded-full bg-gradient-to-r from-orange-500 to-pink-500 text-white">
                  {'\u26A1'} LIMITED TIME
                </div>
                <div className={`mt-3 text-2xl font-extrabold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>Extra 10% off</div>
                <div className={`mt-2 text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                  On selected categories. Explore trending deals now.
                </div>
                <div className="mt-5 flex gap-3">
                  <Link to="/products?sort=rating_desc" className="flex-1 text-center px-4 py-2 rounded-2xl bg-gradient-to-r from-blue-600 to-cyan-500 text-white font-semibold">
                    Shop Now
                  </Link>
                  <Link
                    to="/contact"
                    className={`flex-1 text-center px-4 py-2 rounded-2xl font-semibold border ${
                      isDarkMode ? 'border-white/10 text-gray-200 hover:bg-white/5' : 'border-gray-300 text-gray-800 hover:bg-white'
                    }`}
                  >
                    Help
                  </Link>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Deals (featured) */}
      <section className={`rounded-2xl border overflow-hidden ${isDarkMode ? 'bg-gray-900/60 border-white/10' : 'bg-white border-gray-200'}`}>
        <div className="p-5 md:p-6 flex items-center justify-between">
          <div>
            <div className={`text-sm font-bold tracking-wide ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>DEALS</div>
            <div className={`text-2xl font-extrabold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>Trending Now</div>
          </div>
          <Link to="/products?sort=rating_desc" className="px-4 py-2 rounded-2xl bg-gradient-to-r from-blue-600 to-cyan-500 text-white font-semibold">
            View All
          </Link>
        </div>

        {loading ? (
          <div className={`px-6 pb-6 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>Loading…</div>
        ) : featured.length ? (
          <div className="px-5 pb-6 grid sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {featured.slice(0, 8).map((p, idx) => (
              <div
                key={p._id}
                className={`${isDarkMode ? 'bg-black/30' : 'bg-white'} rounded-2xl border ${isDarkMode ? 'border-white/10' : 'border-gray-200'} overflow-hidden`}
              >
                <ProductCard product={p} index={idx} />
              </div>
            ))}
          </div>
        ) : (
          <div className={`px-6 pb-6 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
            No products yet. Run the marketplace seed to see deals.
          </div>
        )}
      </section>

      {/* Bottom trust strip */}
      <section className="grid md:grid-cols-3 gap-3">
        {[
          { title: 'Fast Delivery', body: 'Quick doorstep delivery.', icon: '\u26A1' },
          { title: 'Secure Payments', body: 'Safe checkout options.', icon: '\uD83D\uDD12' },
          { title: 'Support', body: 'Help when you need it.', icon: '\uD83D\uDCAC' }
        ].map((b) => (
          <div key={b.title} className={`rounded-2xl border p-5 ${isDarkMode ? 'bg-gray-900/60 border-white/10' : 'bg-white border-gray-200'}`}>
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-2xl bg-gradient-to-r from-blue-600 to-cyan-500 text-white flex items-center justify-center font-bold">
                {b.icon}
              </div>
              <div className={`font-extrabold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>{b.title}</div>
            </div>
            <div className={`mt-2 text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>{b.body}</div>
          </div>
        ))}
      </section>
    </div>
  );
};

export default HomeRebuild;
